import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** The job JSON shape returned by every endpoint that exposes a job. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

/** A raw `jobs` row, as stored in SQLite. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress: number;
  result_output: string | null;
  error: string | null;
  created_at: string;
  updated_at: string;
  run_after: number;
  idem_key: string | null;
  idem_payload: string | null;
}

const SCHEMA = `
CREATE TABLE IF NOT EXISTS jobs (
  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  id TEXT UNIQUE NOT NULL,
  status TEXT NOT NULL,
  input TEXT NOT NULL,
  steps INTEGER NOT NULL,
  fail_attempts INTEGER NOT NULL,
  attempts INTEGER NOT NULL DEFAULT 0,
  progress INTEGER NOT NULL DEFAULT 0,
  result_output TEXT,
  error TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  run_after INTEGER NOT NULL DEFAULT 0,
  idem_key TEXT UNIQUE,
  idem_payload TEXT
);
CREATE INDEX IF NOT EXISTS jobs_claim ON jobs (status, run_after, seq);
CREATE TABLE IF NOT EXISTS heartbeat (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  last_seen INTEGER NOT NULL
);
`;

/** A worker whose heartbeat is older than this is reported as down. */
export const HEARTBEAT_FRESH_MS = 3000;

/**
 * Opens the SQLite database shared by the server and worker processes, and makes sure the schema exists.
 * Both processes call this on start, so either one may start first.
 */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  db.exec(SCHEMA);
  return db;
}

export function nowIso(): string {
  return new Date().toISOString();
}

/** Maps a raw row to the public job JSON shape. */
export function rowToJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress, total: row.steps },
    result: row.status === 'completed' ? { output: row.result_output ?? '' } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

/** Records that the worker is alive at `now` (epoch ms). Passing 0 marks it as stopped. */
export function writeHeartbeat(db: DatabaseSync, now: number = Date.now()): void {
  db.prepare(
    'INSERT INTO heartbeat (id, last_seen) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET last_seen = excluded.last_seen',
  ).run(now);
}

/** True when the worker's heartbeat is fresh enough to count as up. */
export function isWorkerUp(db: DatabaseSync, now: number = Date.now()): boolean {
  const row = db.prepare('SELECT last_seen FROM heartbeat WHERE id = 1').get();
  if (row === undefined) return false;
  return now - Number(row.last_seen) < HEARTBEAT_FRESH_MS;
}

