import { setTimeout as sleep } from 'node:timers/promises';
import { nowIso, openDatabase, writeHeartbeat, type JobRow } from './db.ts';

const STEP_MS = 100;
const POLL_MS = 200;
const RETRY_DELAY_MS = 500;
const HEARTBEAT_MS = 500;
const MAX_ATTEMPTS = 3;
const SHUTDOWN_FALLBACK_MS = 4000;

const db = openDatabase();
let stopping = false;

function beat(): void {
  try {
    writeHeartbeat(db);
  } catch (e) {
    console.error('heartbeat failed:', e);
  }
}
beat();
const heartbeatTimer = setInterval(beat, HEARTBEAT_MS);

// An attempt interrupted by a crash is rolled back: its attempt count is removed so that it is
// re-run as the same attempt number. This keeps `attempts` within 3 and failAttempts deterministic.
db.prepare(
  "UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress = 0, run_after = 0, updated_at = ? WHERE status = 'running'",
).run(nowIso());

const claimStmt = db.prepare(
  `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress = 0, updated_at = ?
   WHERE seq = (SELECT seq FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1)
   RETURNING *`,
);

function claim(): JobRow | undefined {
  const now = Date.now();
  return claimStmt.get(nowIso(), now) as unknown as JobRow | undefined;
}

function requeueInterrupted(id: string): void {
  db.prepare(
    "UPDATE jobs SET status = 'queued', attempts = attempts - 1, progress = 0, run_after = 0, updated_at = ? WHERE id = ?",
  ).run(nowIso(), id);
}

function failAttempt(job: JobRow, attempt: number): void {
  if (attempt < MAX_ATTEMPTS) {
    db.prepare("UPDATE jobs SET status = 'queued', run_after = ?, updated_at = ? WHERE id = ?").run(
      Date.now() + RETRY_DELAY_MS,
      nowIso(),
      job.id,
    );
  } else {
    db.prepare("UPDATE jobs SET status = 'failed', error = 'transient failure', result_output = NULL, updated_at = ? WHERE id = ?").run(
      nowIso(),
      job.id,
    );
  }
}

function setProgress(id: string, completed: number): void {
  db.prepare('UPDATE jobs SET progress = ?, updated_at = ? WHERE id = ?').run(completed, nowIso(), id);
}

function complete(job: JobRow): void {
  db.prepare(
    "UPDATE jobs SET status = 'completed', result_output = ?, progress = steps, error = NULL, updated_at = ? WHERE id = ?",
  ).run(job.input.toUpperCase(), nowIso(), job.id);
}

/** Runs one claimed attempt. `job.attempts` already includes this attempt. */
async function runAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;
  for (let step = 1; step <= job.steps; step++) {
    if (stopping) {
      requeueInterrupted(job.id);
      return;
    }
    await sleep(STEP_MS);
    if (step === 1 && attempt <= job.fail_attempts) {
      failAttempt(job, attempt);
      return;
    }
    setProgress(job.id, step);
  }
  complete(job);
}

async function loop(): Promise<void> {
  while (!stopping) {
    let job: JobRow | undefined;
    try {
      job = claim();
    } catch (e) {
      console.error('claim failed:', e);
    }
    if (job === undefined) {
      await sleep(POLL_MS);
      continue;
    }
    try {
      await runAttempt(job);
    } catch (e) {
      console.error(`job ${job.id} attempt failed:`, e);
    }
  }
}

function onSignal(): void {
  stopping = true;
  // Fallback in case the loop is stuck mid-statement; the normal path exits well before this.
  setTimeout(() => process.exit(0), SHUTDOWN_FALLBACK_MS).unref();
}
process.on('SIGTERM', onSignal);
process.on('SIGINT', onSignal);

console.log('worker started');
await loop();

clearInterval(heartbeatTimer);
try {
  writeHeartbeat(db, 0);
} catch {
  // best effort: the heartbeat goes stale on its own after 3 s
}
db.close();
process.exit(0);

