function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(
  res: ServerResponse,
  status: number,
  code: string,
  message: string,
  fields?: FieldError[],
  headers: Record<string, string> = {},
): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields !== undefined) error.fields = fields;
  send(res, status, { error }, headers);
}

function readBody(req: IncomingMessage): Promise<{ raw: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      if (tooLarge) return;
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        chunks.length = 0;
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve({ raw: tooLarge ? '' : Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

type Validation = { ok: true; value: NewJob } | { ok: false; fields: FieldError[] };

/** Validates a POST /api/jobs request. Collects every problem so the client sees all offending fields. */
function validateCreate(headers: IncomingMessage['headers'], raw: string): Validation {
  const fields: FieldError[] = [];

  const idemHeader = headers['idempotency-key'];
  if (idemHeader !== undefined && !IDEMPOTENCY_KEY_RE.test(idemHeader)) {
    fields.push({ field: 'Idempotency-Key', message: 'Must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  const mediaType = (headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
    return { ok: false, fields };
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    fields.push({ field: 'body', message: 'Body must be valid JSON' });
    return { ok: false, fields };
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    fields.push({ field: 'body', message: 'Body must be a JSON object' });
    return { ok: false, fields };
  }

  const obj = parsed as Record<string, unknown>;
  for (const key of Object.keys(obj)) {
    if (!BODY_FIELDS.has(key)) fields.push({ field: key, message: 'Unknown field' });
  }

  let input = '';
  if (!Object.hasOwn(obj, 'input')) {
    fields.push({ field: 'input', message: 'Required' });
  } else if (typeof obj.input !== 'string') {
    fields.push({ field: 'input', message: 'Must be a string' });
  } else if (obj.input.length < 1 || obj.input.length > 1000 || obj.input.trim().length === 0) {
    fields.push({ field: 'input', message: 'Must be 1 to 1000 characters and not only whitespace' });
  } else {
    input = obj.input;
  }

  const intField = (name: 'steps' | 'failAttempts', min: number, max: number, fallback: number): number => {
    if (!Object.hasOwn(obj, name)) return fallback;
    const v = obj[name];
    if (typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max) return v;
    fields.push({ field: name, message: `Must be an integer from ${min} to ${max}` });
    return fallback;
  };
  const steps = intField('steps', 1, 20, 5);
  const failAttempts = intField('failAttempts', 0, 5, 0);

  if (fields.length > 0) return { ok: false, fields };
  return {
    ok: true,
    value: { input, steps, failAttempts, idemKey: idemHeader ?? null },
  };
}

type CreateOutcome = { kind: 'created' | 'replayed'; row: JobRow } | { kind: 'conflict' };

/**
 * Inserts a job, or finds the existing one for an Idempotency-Key. The check and the insert run in
 * one IMMEDIATE transaction, so two concurrent submissions with the same key cannot both insert.
 */
function createJob(job: NewJob): CreateOutcome {
  const canonical = JSON.stringify({ input: job.input, steps: job.steps, failAttempts: job.failAttempts });
  db.exec('BEGIN IMMEDIATE');
  try {
    let outcome: CreateOutcome | undefined;
    if (job.idemKey !== null) {
      const existing = db.prepare('SELECT * FROM jobs WHERE idem_key = ?').get(job.idemKey) as JobRow | undefined;
      if (existing !== undefined) {
        outcome = existing.idem_payload === canonical ? { kind: 'replayed', row: existing } : { kind: 'conflict' };
      }
    }
    if (outcome === undefined) {
      const id = randomUUID();
      const now = nowIso();
      db.prepare(
        `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress, created_at, updated_at, run_after, idem_key, idem_payload)
         VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)`,
      ).run(id, job.input, job.steps, job.failAttempts, now, now, job.idemKey, job.idemKey === null ? null : canonical);
      const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow;
      outcome = { kind: 'created', row };
    }
    db.exec('COMMIT');
    return outcome;
  } catch (e) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // the transaction may already be closed
    }
    throw e;
  }
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { raw, tooLarge } = await readBody(req);
  if (tooLarge) {
    sendError(res, 400, 'invalid_request', 'Invalid request', [{ field: 'body', message: 'Body is larger than 1 MB' }]);
    return;
  }
  const validation = validateCreate(req.headers, raw);
  if (!validation.ok) {
    sendError(res, 400, 'invalid_request', 'Invalid request', validation.fields);
    return;
  }
  const outcome = createJob(validation.value);
  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload');
    return;
  }
  send(res, outcome.kind === 'created' ? 201 : 200, rowToJob(outcome.row));
}

function handleList(res: ServerResponse): void {
  const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
  send(res, 200, { jobs: rows.map(rowToJob) });
}

function handleGetJob(res: ServerResponse, id: string): void {
  const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow | undefined;
  if (row === undefined) {
    sendError(res, 404, 'not_found', 'Job not found');
    return;
  }
  send(res, 200, rowToJob(row));
}

function handleHealth(res: ServerResponse): void {
  send(res, 200, { status: 'ok', worker: isWorkerUp(db) ? 'up' : 'down' });
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  let allowed: string[] | undefined;
  let jobId: string | undefined;
  if (pathname === '/') allowed = ['GET'];
  else if (pathname === '/health') allowed = ['GET'];
  else if (pathname === '/api/jobs') allowed = ['GET', 'POST'];
  else {
    const m = JOB_PATH_RE.exec(pathname);
    if (m) {
      allowed = ['GET'];
      jobId = m[1]!;
    }
  }

  if (allowed === undefined) {
    sendError(res, 404, 'not_found', 'Not found');
    return;
  }
  if (!allowed.includes(method)) {
    sendError(res, 405, 'method_not_allowed', `Method ${method} not allowed`, undefined, { allow: allowed.join(', ') });
    return;
  }

  if (pathname === '/') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
  } else if (pathname === '/health') {
    handleHealth(res);
  } else if (pathname === '/api/jobs') {
    if (method === 'POST') await handleCreate(req, res);
    else handleList(res);
  } else {
    handleGetJob(res, jobId!);
  }
}

const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (res.headersSent) {
      res.end();
    } else {
      sendError(res, 500, 'internal_error', 'Internal server error');
    }
  });
});

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  server.close();
  server.closeAllConnections();
  db.close();
  process.exit(0);
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

